/** @jsxImportSource preact */
import { useEffect, useRef } from "preact/hooks";
import { mountAddressSearch, type AddressSearchOptions } from "../../components/address-search/AddressSearchEngine.js";
import type { MotionController } from "../../components/address-search/motion-runtime";

export function AddressSearch({ options, className }: { options?: AddressSearchOptions; className?: string }) {
  const host = useRef<HTMLDivElement>(null);
  const controller = useRef<MotionController | null>(null);
  useEffect(() => {
    const instance = mountAddressSearch(host.current!, options);
    controller.current = instance;
    return () => { instance.destroy(); controller.current = null; };
    // Options are updated below without remounting the state machine.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  useEffect(() => { controller.current?.update(options ?? {}); }, [options]);
  return <div ref={host} className={className} data-motion-component="address-search" />;
}

